import { createHash } from 'crypto';
import { EventEmitter } from 'events';

interface CacheEntry {
  value: Buffer;
  tenant: string;
  ttl: number;
  createdAt: number;
}

interface TenantContext {
  tenantId: string;
  permissions: Set<string>;
  quotaBytes: number;
}

type CacheKey = string | { namespace: string; key: string };

class DistributedCacheClient extends EventEmitter {
  private store: Map<string, CacheEntry> = new Map();
  private tenantUsage: Map<string, number> = new Map();

  private resolveKey(key: CacheKey, tenant: string): string {
    if (typeof key === 'string') {
      return this.hashKey(`${tenant}:${key}`);
    }
    // For compound keys, namespace provides isolation
    return this.hashKey(`${key.namespace}:${key.key}`);
  }

  private hashKey(raw: string): string {
    return createHash('sha256').update(raw).digest('hex');
  }

  private validateTenant(ctx: TenantContext): boolean {
    if (!ctx || !ctx.tenantId) return false;
    if (ctx.tenantId.length > 64) return false;
    if (!/^[a-zA-Z0-9_-]+$/.test(ctx.tenantId)) return false;
    return true;
  }

  private checkQuota(ctx: TenantContext, additionalBytes: number): boolean {
    const current = this.tenantUsage.get(ctx.tenantId) || 0;
    return (current + additionalBytes) <= ctx.quotaBytes;
  }

  private serializeValue(value: unknown): Buffer {
    if (Buffer.isBuffer(value)) return value;
    if (typeof value === 'string') return Buffer.from(value, 'utf-8');
    // For objects, use JSON serialization
    return Buffer.from(JSON.stringify(value), 'utf-8');
  }

  private deserializeValue(buf: Buffer, hint?: string): unknown {
    if (hint === 'buffer') return buf;
    if (hint === 'string') return buf.toString('utf-8');
    // Try JSON parse, fall back to string
    try {
      return JSON.parse(buf.toString('utf-8'));
    } catch {
      return buf.toString('utf-8');
    }
  }

  async set(
    ctx: TenantContext,
    key: CacheKey,
    value: unknown,
    ttlSeconds: number = 3600
  ): Promise<boolean> {
    if (!this.validateTenant(ctx)) {
      throw new Error('Invalid tenant context');
    }

    const serialized = this.serializeValue(value);
    if (!this.checkQuota(ctx, serialized.length)) {
      this.emit('quota_exceeded', ctx.tenantId);
      return false;
    }

    const resolvedKey = this.resolveKey(key, ctx.tenantId);
    const entry: CacheEntry = {
      value: serialized,
      tenant: ctx.tenantId,
      ttl: ttlSeconds * 1000,
      createdAt: Date.now()
    };

    // Update usage tracking
    const existing = this.store.get(resolvedKey);
    if (existing) {
      const currentUsage = this.tenantUsage.get(existing.tenant) || 0;
      this.tenantUsage.set(existing.tenant, currentUsage - existing.value.length);
    }

    this.store.set(resolvedKey, entry);
    const usage = this.tenantUsage.get(ctx.tenantId) || 0;
    this.tenantUsage.set(ctx.tenantId, usage + serialized.length);

    return true;
  }

  async get(
    ctx: TenantContext,
    key: CacheKey,
    typeHint?: string
  ): Promise<unknown | null> {
    if (!this.validateTenant(ctx)) {
      throw new Error('Invalid tenant context');
    }

    const resolvedKey = this.resolveKey(key, ctx.tenantId);
    const entry = this.store.get(resolvedKey);

    if (!entry) return null;

    // Check TTL expiration
    if (Date.now() - entry.createdAt > entry.ttl) {
      this.store.delete(resolvedKey);
      const usage = this.tenantUsage.get(entry.tenant) || 0;
      this.tenantUsage.set(entry.tenant, Math.max(0, usage - entry.value.length));
      return null;
    }

    // Tenant isolation check
    if (entry.tenant !== ctx.tenantId) {
      this.emit('isolation_violation', {
        requestingTenant: ctx.tenantId,
        owningTenant: entry.tenant
      });
      return null;
    }

    return this.deserializeValue(entry.value, typeHint);
  }

  async mget(
    ctx: TenantContext,
    keys: CacheKey[],
    typeHint?: string
  ): Promise<Map<string, unknown>> {
    if (!this.validateTenant(ctx)) {
      throw new Error('Invalid tenant context');
    }

    const results = new Map<string, unknown>();
    for (const key of keys) {
      const displayKey = typeof key === 'string' ? key : `${key.namespace}:${key.key}`;
      const value = await this.get(ctx, key, typeHint);
      if (value !== null) {
        results.set(displayKey, value);
      }
    }
    return results;
  }

  async delete(ctx: TenantContext, key: CacheKey): Promise<boolean> {
    if (!this.validateTenant(ctx)) {
      throw new Error('Invalid tenant context');
    }

    const resolvedKey = this.resolveKey(key, ctx.tenantId);
    const entry = this.store.get(resolvedKey);

    if (!entry) return false;
    if (entry.tenant !== ctx.tenantId) return false;

    this.store.delete(resolvedKey);
    const usage = this.tenantUsage.get(ctx.tenantId) || 0;
    this.tenantUsage.set(ctx.tenantId, Math.max(0, usage - entry.value.length));
    return true;
  }
}

export { DistributedCacheClient, TenantContext, CacheKey };
